import{_ as l,a0 as a,w as i,s,ao as c,I as o,x as p,a1 as e,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"實例學習 Linux 的 cd 命令，及對內部命令的解釋 | LCTT x X-CMD","titleTemplate":false,"description":"實例學習 Linux 的 cd 命令，及對內部命令的解釋 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"實例學習 Linux 的 cd 命令，及對內部命令的解釋 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"實例學習 Linux 的 cd 命令，及對內部命令的解釋 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Understanding Linux cd Command with Examples","title":"實例學習 Linux 的 cd 命令，及對內部命令的解釋","tag":"201401","desc":""},"relativePath":"201401/Understanding Linux cd Command with Examples.md","filePath":"[post].md"}'),m={name:"201401/Understanding Linux cd Command with Examples.md"};function r(h,t,x,u,g,_){const n=a("Link");return i(),s("div",null,[t[11]||(t[11]=c('<h1 id="實例學習-linux-的-cd-命令-及對內部命令的解釋" tabindex="-1">實例學習 Linux 的 cd 命令，及對內部命令的解釋 <a class="header-anchor" href="#實例學習-linux-的-cd-命令-及對內部命令的解釋" aria-label="Permalink to “實例學習 Linux 的 cd 命令，及對內部命令的解釋”">​</a></h1><p>在 *nix 的世界裏，cd 命令是最為基礎的命令，它所做的是改變當前的工作目錄。 本文將深入講解關於 cd 的技術細節。</p><h3 id="cd-命令-一個內部命令" tabindex="-1">cd 命令：一個內部命令 <a class="header-anchor" href="#cd-命令-一個內部命令" aria-label="Permalink to “cd 命令：一個內部命令”">​</a></h3><p>絕大多數的 Linux 發行版都將 Bash Shell 用作默認的 Shell。Bash 有一些自己內部的命令，cd 就是其中一個。我將會解釋究竟什麼是內部命令，以及為什麼 cd 會是一個內部命令。</p><p>那麼首先，請檢查確認你的當前 shell 以及環境變量：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/01.cd_shell.png" alt=""></p><p>現在繼續使用 which 命令來檢查 cd 所在的路徑：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/02.cd_which.png" alt=""></p><p>我們發現沒有輸出。因為在我們的系統中 cd 命令其實並沒有對應某個 binary，但是我們卻又仍然可以執行這個命令，這就是因為 cd 其實是 BASH 的一個內部命令。內部命令都是被整合進入 shell 裏面的。接下來我們可以繼續使用 type 命令來查看 cd 這個內部命令的更多信息。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/03.cd_type.png" alt=""></p><p>如果你嘗試去查看內部命令的手冊，會發現並沒有為它們單獨設置手冊。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/04.cd_man.png" alt=""></p><p>對於這些內部命令來説，並沒有創建單獨的進程，因此它們執行起來非常快。</p><p>我們可以使用 help 命令來查看所有的內部命令（help 命令本身也是一個內部命令）：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/05.cd_help_1.png" alt=""></p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/06.cd_help_2.png" alt=""></p><h3 id="為什麼-cd-會是一個內部命令" tabindex="-1">為什麼 cd 會是一個內部命令 <a class="header-anchor" href="#為什麼-cd-會是一個內部命令" aria-label="Permalink to “為什麼 cd 會是一個內部命令”">​</a></h3><p>讓我們從簡單的開始聊起吧。我不會説太多繁瑣細節，但是想要弄明白這個問題，還是需要對 Unix 進程有一點了解。</p><p>不管 BASH 什麼時候創建了一個進程，這個進程事實上都是在 BASH 的一個子 shell 中運行（也就是當前 BASH 進程的子進程）。這些新的進程會做一些改變，或是顯示一些東西（如果需要的話），以及當這個進程死亡的時候，子 shell 並不會向當前 BASH 返回信息。請注意，cd 所做的是改變 shell 的 PWD。 因此倘若 cd 是一個外部命令，那麼它改變的將會是子 shell 的 PWD，也不會向父 shell 返回任何東西。所以，當前 shell 的 PWD 就不會做任何改變。<strong>所有能對當前 shell的環境作出改變的命令都必須是內部命令。</strong> 因此如果我們將 cd 做成外部命令，就無法像原來一樣改變當前目錄了。</p><p>好了，現在讓我們再來聊聊 cd 命令的用法。</p><h3 id="cd-命令的用法" tabindex="-1">cd 命令的用法： <a class="header-anchor" href="#cd-命令的用法" aria-label="Permalink to “cd 命令的用法：”">​</a></h3><p>如果你不加任何參數地來使用 cd 命令，不管你現在在哪，都會把你帶到<strong>你的</strong> home 目錄下。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/07.cd_home.png" alt=""></p><p>其實波浪線符號（~）代表的也是 home 目錄，我們同樣可以用它回到 home（譯註：通常用~配合其下的子目錄名，來切換到自己home下的子目錄，如：cd ~/Desktop）。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/08.cd_home_tilde.png" alt=""></p><p>如果你是 root 用户，你可以通過使用波浪號加任何一個用户名來切換到該用户的 home 目錄下。在一些 Linux 發行版中，沒有特權的用户默認是沒有權限訪問其他用户的 home 目錄的。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/09.cd_home_user.png" alt=""></p><p>再來看，. 目錄代表的是當前目錄，而 .. 代表的是上級目錄。所以我們可以使用 .. 來回到上級目錄。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/10.cd_parent.png" alt=""></p><p>大部分情況下，cd . 是不會改變你的 PWD。舉例來看：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/11.cd_dot.png" alt=""></p><p>但是如果你的當前目錄已經被重命名了，那麼你的 PWD 就會發生改變：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/12.cd_dot_renamed.png" alt=""></p><p>在 BASH 和大部分其他的 shell 中，你可以提供兩種不同的路徑：絕對路徑和相對路徑。絕對路徑以 / 開始，並且和你的 PWD 無關。而相對路徑不會以 / 開始，並且和你的 PWD 相關。</p><p>使用絕對路徑來改變 PWD：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/13.cd_abs_path.png" alt=""></p><p>使用相對路徑來改變 PWD：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/14cd_rel_path.png" alt=""></p><p>我們可以在兩個目錄切換：</p><p>cd - 命令可以返回上一次的工作目錄，我們可以使用它在兩個不同的目錄中快速切換。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/15.cd_toggle.png" alt=""></p><p>我們上一次的工作目錄會被儲存在 OLDPWD 這個變量中。但是如果你在一個新開啓的終端中來使用的話，會報出下面的錯誤：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/16.cd_OLDPWD_not_set.png" alt=""></p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/16.cd_OLDPWD_not_set.png" alt=""></p><p>你可以配合 cd 命令來使用一些 bash 小技巧。</p><p>比如，不妨使用 <em>?</em> 這個萬能藥：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/17.cd_question_mark_wild_card.png" alt=""></p><p>使用 *：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/18.cd_star_wild_card.png" alt=""></p><hr>',50)),o("p",null,[t[1]||(t[1]=p("via: ",-1)),e(n,{href:"http://linoxide.com/linux-command/linux-cd-command-examples/"},{default:d(()=>[...t[0]||(t[0]=[p("http://linoxide.com/linux-command/linux-cd-command-examples/",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=p("譯者：",-1)),e(n,{href:"https://github.com/ailurus1991"},{default:d(()=>[...t[2]||(t[2]=[p("ailurus1991",-1)])]),_:1}),t[5]||(t[5]=p(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:d(()=>[...t[3]||(t[3]=[p("wxy",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=p("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[6]||(t[6]=[p("LCTT",-1)])]),_:1}),t[9]||(t[9]=p(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:d(()=>[...t[7]||(t[7]=[p("Linux中國",-1)])]),_:1}),t[10]||(t[10]=p(" 榮譽推出",-1))])])}const T=l(m,[["render",r]]);export{f as __pageData,T as default};
